# StockLens AI v2.2 — embedded dashboard
# Source of truth: this file. index.html is a byte-identical copy.
DASHBOARD_HTML = '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>StockLens</title>\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link href="https://fonts.googleapis.com/css2?family=Newsreader:ital,opsz,wght@0,6..72,400;0,6..72,500;1,6..72,400&family=IBM+Plex+Sans:wght@400;500;600&display=swap" rel="stylesheet">\n<style>\n:root{\n  --paper:#EEF0EA;\n  --ink:#1B2A2E;\n  --rule:#C9CFC6;\n  --band:#2E6F6B;\n  --loss:#8A3A2E;\n  --quiet:#6E7A74;\n  --panel:#F7F8F5;\n}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%}\nbody{\n  margin:0;background:var(--paper);color:var(--ink);\n  font:400 16px/1.55 "IBM Plex Sans",system-ui,-apple-system,sans-serif;\n  font-variant-numeric:tabular-nums;\n}\n.sheet{max-width:860px;margin:0 auto;padding:0 22px 96px}\n\n/* masthead */\n.masthead{display:flex;justify-content:space-between;align-items:baseline;gap:16px;\n  padding:26px 0 14px;border-bottom:1px solid var(--ink)}\n.wordmark{font:500 25px/1 "Newsreader",Georgia,serif;letter-spacing:-.01em}\n.regime{font-size:13px;color:var(--quiet)}\n.regime b{color:var(--ink);font-weight:500}\n\n/* tabs */\nnav{display:flex;gap:26px;border-bottom:1px solid var(--rule);margin-bottom:34px}\nnav button{\n  appearance:none;background:none;border:0;padding:13px 0;margin-bottom:-1px;\n  font:500 15px/1 "IBM Plex Sans",sans-serif;color:var(--quiet);\n  border-bottom:2px solid transparent;cursor:pointer\n}\nnav button:hover{color:var(--ink)}\nnav button[aria-selected="true"]{color:var(--ink);border-bottom-color:var(--band)}\n\n/* hero */\n.lede{font:400 29px/1.32 "Newsreader",Georgia,serif;max-width:19ch;margin:0 0 14px}\n.lede .figure{font-size:62px;line-height:.9;display:block;margin:6px 0 2px;letter-spacing:-.02em}\n.sub{color:var(--quiet);max-width:62ch;margin:0 0 30px;font-size:15px}\n.sub a{color:var(--band)}\n\n/* controls */\n.controls{display:flex;flex-wrap:wrap;gap:14px;align-items:flex-end;\n  padding:20px 0 24px;border-top:1px solid var(--rule);border-bottom:1px solid var(--rule)}\n.field{display:flex;flex-direction:column;gap:6px;min-width:0}\n.field label{font-size:13px;color:var(--quiet)}\n.field .input,.field select{\n  height:44px;background:var(--panel);border:1px solid var(--rule);border-radius:2px;\n  color:var(--ink);padding:0 12px;font:400 16px/1 "IBM Plex Sans",sans-serif;\n  font-variant-numeric:tabular-nums\n}\n.field .input{display:flex;align-items:center;gap:5px;min-width:150px}\n.field .input input{width:100%;min-width:0;background:none;border:0;outline:0;color:inherit;\n  font:inherit;font-variant-numeric:tabular-nums}\n.field select{min-width:132px}\n.run{\n  height:44px;padding:0 22px;border:1px solid var(--ink);border-radius:2px;\n  background:var(--ink);color:var(--paper);cursor:pointer;\n  font:500 15px/1 "IBM Plex Sans",sans-serif\n}\n.run:hover{background:var(--band);border-color:var(--band)}\n.run[disabled]{opacity:.45;cursor:default}\n:focus-visible{outline:2px solid var(--band);outline-offset:2px}\n\n/* price filter */\n.filter{padding:20px 0;border-bottom:1px solid var(--rule)}\n.filter h2{font:500 17px/1.3 "IBM Plex Sans",sans-serif;margin:0 0 4px}\n.filter p{margin:0 0 16px;font-size:14px;color:var(--quiet)}\n.slider{position:relative;height:36px}\n.slider:before{content:"";position:absolute;left:0;right:0;top:17px;height:2px;background:var(--rule)}\n.slider input{position:absolute;left:0;top:3px;width:100%;height:30px;margin:0;background:none;\n  pointer-events:none;-webkit-appearance:none;appearance:none}\n.slider input::-webkit-slider-thumb{-webkit-appearance:none;width:18px;height:18px;border-radius:50%;\n  background:var(--band);border:2px solid var(--paper);pointer-events:auto;cursor:pointer}\n.slider input::-moz-range-thumb{width:16px;height:16px;border-radius:50%;background:var(--band);\n  border:2px solid var(--paper);pointer-events:auto;cursor:pointer}\n.chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:6px}\n.chips button{height:32px;padding:0 12px;background:none;border:1px solid var(--rule);border-radius:2px;\n  color:var(--quiet);font:400 14px/1 "IBM Plex Sans",sans-serif;cursor:pointer}\n.chips button:hover{border-color:var(--band);color:var(--band)}\n\n/* status */\n.status{padding:22px 0;font-size:14px;color:var(--quiet)}\n.status b{color:var(--ink);font-weight:500}\n\n/* ledger entries */\n.entry{display:grid;grid-template-columns:52px 1fr;gap:0 18px;\n  padding:26px 0;border-top:1px solid var(--rule)}\n.rank{font:400 34px/1 "Newsreader",Georgia,serif;color:var(--band)}\n.head{display:flex;justify-content:space-between;align-items:baseline;gap:16px}\n.name{font:500 21px/1.2 "IBM Plex Sans",sans-serif;margin:0}\n.score{font:400 27px/1 "Newsreader",Georgia,serif;white-space:nowrap}\n.score i{font-style:normal;font-size:13px;color:var(--quiet);font-family:"IBM Plex Sans",sans-serif}\n.line{margin:5px 0 0;font-size:14px;color:var(--quiet)}\n.signal{font:500 14px/1 "IBM Plex Sans",sans-serif;padding:5px 9px;border-radius:2px;\n  border:1px solid currentColor}\n.buy{color:var(--band)}\n.sell{color:var(--loss)}\n\n/* distribution strip — the one loud element */\n.dist{margin:22px 0 6px}\n.dist-cap{font-size:13px;color:var(--quiet);margin-bottom:14px}\n.track{position:relative;height:30px}\n.track:before{content:"";position:absolute;left:0;right:0;top:14px;height:1px;background:var(--rule)}\n.whisker{position:absolute;top:14px;height:1px;background:var(--loss)}\n.range{position:absolute;top:8px;height:13px;background:var(--band);opacity:.22}\n.median{position:absolute;top:4px;width:2px;height:21px;background:var(--band)}\n.zero{position:absolute;top:0;width:1px;height:30px;background:var(--ink)}\n.zero:after{content:"0";position:absolute;top:30px;left:-3px;font-size:11px;color:var(--ink)}\n.ticks{position:relative;height:20px;margin-top:6px;font-size:12px;color:var(--quiet)}\n.ticks span{position:absolute;transform:translateX(-50%);white-space:nowrap}\n.dist-note{font-size:13px;color:var(--quiet);margin-top:10px}\n\n/* data rows */\n.rows{margin-top:20px;border-top:1px solid var(--rule)}\n.row{display:flex;justify-content:space-between;gap:16px;padding:9px 0;\n  border-bottom:1px solid var(--rule);font-size:14px}\n.row span{color:var(--quiet)}\n.row b{font-weight:500}\n.why{margin-top:18px;font-size:14px;color:var(--quiet)}\n.why ul{margin:6px 0 0;padding-left:18px}\n.why li{margin:3px 0}\n.why strong{color:var(--ink);font-weight:500}\n\n/* backtest */\n.metrics{border-top:1px solid var(--rule)}\n.caveat{margin-top:26px;padding-top:18px;border-top:1px solid var(--rule);\n  font-size:14px;color:var(--quiet);max-width:68ch}\n.caveat h3{font:500 15px/1.3 "IBM Plex Sans",sans-serif;color:var(--ink);margin:0 0 8px}\n.caveat ul{margin:0;padding-left:18px}\n.caveat li{margin:4px 0}\ntable{width:100%;border-collapse:collapse;font-size:14px;margin-top:8px}\nth{text-align:right;font-weight:500;color:var(--quiet);padding:8px 0;\n  border-bottom:1px solid var(--ink);font-size:13px}\nth:first-child,td:first-child{text-align:left}\ntd{text-align:right;padding:9px 0;border-bottom:1px solid var(--rule)}\n.scroll{overflow-x:auto}\n\n.empty{padding:40px 0;border-top:1px solid var(--rule);color:var(--quiet);max-width:56ch}\n.empty b{display:block;color:var(--ink);font-weight:500;font-size:17px;margin-bottom:5px}\n.foot{margin-top:52px;padding-top:18px;border-top:1px solid var(--ink);\n  font-size:13px;color:var(--quiet);max-width:66ch}\n.hide{display:none!important}\n\n@media (max-width:620px){\n  .sheet{padding:0 16px 72px}\n  .lede{font-size:25px}\n  .lede .figure{font-size:52px}\n  .entry{grid-template-columns:1fr;gap:0}\n  .rank{font-size:20px;margin-bottom:2px}\n  .controls{gap:12px}\n  .field,.field .input,.field select{width:100%}\n  .run{width:100%}\n  .head{flex-direction:column;gap:2px}\n}\n@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}\n</style>\n</head>\n<body>\n<div class="sheet">\n\n<div class="masthead">\n  <div class="wordmark">StockLens</div>\n  <div class="regime" id="regime">Frozen model, v2.1</div>\n</div>\n\n<nav role="tablist">\n  <button role="tab" aria-selected="true" onclick="mode(\'invest\',this)">Monthly ranking</button>\n  <button role="tab" aria-selected="false" onclick="mode(\'day\',this)">Intraday</button>\n  <button role="tab" aria-selected="false" onclick="mode(\'backtest\',this)">What it measured</button>\n</nav>\n\n<h1 class="lede" id="lede">This model beat the NIFTY in\n  <span class="figure">49%</span> of backtested months.</h1>\n<p class="sub" id="sub">Which is to say: slightly worse than a coin toss in any given month. It\n  ranks about 190 NSE stocks on trend and volatility and splits your money across a basket. Every\n  range below is measured from what those stocks actually did — not predicted.</p>\n\n<section id="filter" class="filter hide">\n  <h2 id="priceText">Any affordable price</h2>\n  <p>Applies to intraday scans only.</p>\n  <div class="slider">\n    <input id="minPrice" type="range" min="0" max="5000" step="50" value="0"\n      aria-label="Minimum share price" oninput="priceChanged(\'min\')">\n    <input id="maxPrice" type="range" min="0" max="5000" step="50" value="5000"\n      aria-label="Maximum share price" oninput="priceChanged(\'max\')">\n  </div>\n  <div class="chips">\n    <button onclick="preset(0,5000)">Any price</button>\n    <button onclick="preset(0,200)">Under ₹200</button>\n    <button onclick="preset(0,500)">Under ₹500</button>\n    <button onclick="preset(500,1000)">₹500 to ₹1,000</button>\n    <button onclick="preset(1000,2500)">₹1,000 to ₹2,500</button>\n  </div>\n</section>\n\n<section id="mainControls" class="controls">\n  <div class="field">\n    <label for="amount">Amount to invest</label>\n    <div class="input">₹<input id="amount" type="number" value="5000" min="1000" step="500"></div>\n  </div>\n  <div class="field hide" id="riskpct">\n    <label for="rp">Risk per trade</label>\n    <select id="rp">\n      <option value=".5">0.5% of capital</option>\n      <option value="1" selected>1% of capital</option>\n      <option value="1.5">1.5% of capital</option>\n      <option value="2">2% of capital</option>\n    </select>\n  </div>\n  <div class="field hide" id="limitbox">\n    <label for="limit">Stocks to scan</label>\n    <select id="limit">\n      <option>5</option>\n      <option selected>10</option>\n      <option>20</option>\n    </select>\n  </div>\n  <button class="run" id="go" onclick="run()">Build a basket</button>\n</section>\n\n<section id="backtestControls" class="controls hide">\n  <div class="field">\n    <label for="btEngine">Engine</label>\n    <select id="btEngine" onchange="backtestEngineChanged()">\n      <option value="strategy" selected>Monthly basket, after costs and tax</option>\n      <option value="intraday">Intraday, live rules</option>\n      <option value="monthly">Monthly, technical proxy</option>\n    </select>\n  </div>\n  <div class="field">\n    <label for="btLimit">Sample size</label>\n    <select id="btLimit">\n      <option value="3" selected>3 stocks, faster</option>\n      <option value="5">5 stocks</option>\n    </select>\n  </div>\n  <div class="field" id="btStrategyBox">\n    <label for="btHold">Rebalance</label>\n    <select id="btHold">\n      <option value="21" selected>Every month</option>\n      <option value="63">Every quarter</option>\n    </select>\n  </div>\n  <div class="field" id="btBasketBox">\n    <label for="btTopN">Basket</label>\n    <select id="btTopN">\n      <option value="3">3 stocks</option>\n      <option value="8" selected>8 stocks</option>\n      <option value="12">12 stocks</option>\n    </select>\n  </div>\n  <div class="field" id="btRegimeBox">\n    <label for="btRegime">Below the 200-day average</label>\n    <select id="btRegime">\n      <option value="false" selected>Stay invested</option>\n      <option value="true">Move to cash</option>\n    </select>\n  </div>\n  <div class="field" id="btWindowBox">\n    <label for="btWindow">Window</label>\n    <select id="btWindow">\n      <option value="5d">Last 5 trading days</option>\n      <option value="1mo" selected>Last month</option>\n    </select>\n  </div>\n  <div class="field hide" id="btMonthlyBox">\n    <label for="btMonthlyPeriod">History</label>\n    <select id="btMonthlyPeriod">\n      <option value="1y">1 year</option>\n      <option value="2y" selected>2 years</option>\n    </select>\n  </div>\n  <button class="run" onclick="runBacktest()">Run the test</button>\n</section>\n\n<div class="status" id="status">Set an amount, then rank.</div>\n<div id="cards"></div>\n\n<p class="foot">Rankings and historical ranges are research output. They are not advice, and nothing\n  here accounts for brokerage, slippage or capital-gains tax.</p>\n</div>\n\n<script>\nlet current=\'invest\';\n\nconst fmt=n=>new Intl.NumberFormat(\'en-IN\',\n  {style:\'currency\',currency:\'INR\',maximumFractionDigits:0}).format(n);\nconst esc=s=>String(s).replace(/[&<>"]/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\'}[c]));\n\nfunction effectiveMax(){\n  const v=+document.getElementById(\'maxPrice\').value;\n  return v>=5000?0:v;\n}\nfunction priceChanged(which){\n  const lo=document.getElementById(\'minPrice\'),hi=document.getElementById(\'maxPrice\');\n  if(+lo.value>+hi.value){ which===\'min\' ? hi.value=lo.value : lo.value=hi.value; }\n  updatePriceText();\n}\nfunction preset(lo,hi){\n  document.getElementById(\'minPrice\').value=lo;\n  document.getElementById(\'maxPrice\').value=hi;\n  updatePriceText();\n}\nfunction updatePriceText(){\n  const lo=+document.getElementById(\'minPrice\').value,hi=+document.getElementById(\'maxPrice\').value;\n  let t=\'Any affordable price\';\n  if(lo===0&&hi<5000) t=`Up to ${fmt(hi)} a share`;\n  else if(lo>0&&hi>=5000) t=`${fmt(lo)} a share and above`;\n  else if(lo>0) t=`${fmt(lo)} to ${fmt(hi)} a share`;\n  document.getElementById(\'priceText\').textContent=t;\n}\n\nfunction mode(m,btn){\n  current=m;\n  document.querySelectorAll(\'nav button\').forEach(b=>b.setAttribute(\'aria-selected\',\'false\'));\n  btn.setAttribute(\'aria-selected\',\'true\');\n  document.getElementById(\'cards\').innerHTML=\'\';\n\n  const day=m===\'day\',bt=m===\'backtest\';\n  document.getElementById(\'mainControls\').classList.toggle(\'hide\',bt);\n  document.getElementById(\'backtestControls\').classList.toggle(\'hide\',!bt);\n  document.getElementById(\'filter\').classList.toggle(\'hide\',!day);\n  document.getElementById(\'riskpct\').classList.toggle(\'hide\',!day);\n  document.getElementById(\'limitbox\').classList.toggle(\'hide\',!day);\n\n  const lede=document.getElementById(\'lede\'),sub=document.getElementById(\'sub\');\n  if(bt){\n    lede.innerHTML=\'Nothing here is assumed.<span class="figure">Run it.</span>\';\n    sub.textContent=\'Every number on this tab is computed from historical bars when you press the \'+\n      \'button. The intraday test replays the exact live rules. The monthly test is a technical proxy \'+\n      \'and is labelled as one.\';\n    document.getElementById(\'status\').textContent=\'Pick an engine and run the test.\';\n  }else if(day){\n    lede.innerHTML=\'Setups that fit<span class="figure">your capital.</span>\';\n    sub.textContent=\'Scans for entries against VWAP, EMA, RSI and volume, then sizes the position so a \'+\n      \'stop-out costs you the percentage you chose. A score is not a probability of profit.\';\n    document.getElementById(\'go\').textContent=\'Scan for setups\';\n    document.getElementById(\'status\').textContent=\'Set your capital and risk, then scan.\';\n  }else{\n    lede.innerHTML=\'This model beat the NIFTY in<span class="figure">49%</span> of backtested months.\';\n    sub.textContent=\'Which is to say: slightly worse than a coin toss in any given month. It ranks \'+\n      \'about 190 NSE stocks on trend and volatility and splits your money across a basket. Every \'+\n      \'range below is measured from what those stocks actually did — not predicted.\';\n    document.getElementById(\'go\').textContent=\'Build a basket\';\n    document.getElementById(\'status\').textContent=\'Set an amount, then rank.\';\n  }\n}\n\nfunction backtestEngineChanged(){\n  const e=document.getElementById(\'btEngine\').value;\n  const strat=e===\'strategy\';\n  [\'btStrategyBox\',\'btBasketBox\',\'btRegimeBox\'].forEach(id=>\n    document.getElementById(id).classList.toggle(\'hide\',!strat));\n  document.getElementById(\'btWindowBox\').classList.toggle(\'hide\',e!==\'intraday\');\n  document.getElementById(\'btMonthlyBox\').classList.toggle(\'hide\',e!==\'monthly\');\n  document.getElementById(\'btLimit\').parentElement.classList.toggle(\'hide\',strat);\n}\n\n/* Plots the measured spread of past 1-month returns against a zero line. */\nfunction strip(h){\n  if(!h) return \'<p class="dist-note">Not enough history to plot a range.</p>\';\n  const lo=Math.min(h.p05,0),hi=Math.max(h.p80,0),pad=(hi-lo)*0.12||1;\n  const a=lo-pad,b=hi+pad,x=v=>((v-a)/(b-a))*100;\n  return `<div class="dist">\n    <div class="dist-cap">Where this stock finished after a month, across ${h.samples} past\n      one-month windows</div>\n    <div class="track">\n      <div class="whisker" style="left:${x(h.p05)}%;width:${x(h.p20)-x(h.p05)}%"></div>\n      <div class="range" style="left:${x(h.p20)}%;width:${x(h.p80)-x(h.p20)}%"></div>\n      <div class="median" style="left:${x(h.median)}%"></div>\n      <div class="zero" style="left:${x(0)}%"></div>\n    </div>\n    <div class="ticks">\n      <span style="left:${x(h.p05)}%">${h.p05}%</span>\n      <span style="left:${x(h.median)}%">${h.median}%</span>\n      <span style="left:${x(h.p80)}%">${h.p80}%</span>\n    </div>\n    <p class="dist-note">Middle band holds 3 in 5 of those months. It closed higher in\n      ${h.positive_rate}% of them.</p>\n  </div>`;\n}\n\nfunction row(label,value){\n  return `<div class="row"><span>${label}</span><b>${value}</b></div>`;\n}\n\nasync function run(){\n  const amount=+document.getElementById(\'amount\').value;\n  const st=document.getElementById(\'status\'),cards=document.getElementById(\'cards\');\n  const go=document.getElementById(\'go\');\n\n  if(current!==\'day\'&&amount<1000){\n    st.textContent=\'Enter at least ₹1,000 so whole shares are affordable.\';\n    return;\n  }\n\n  go.disabled=true;\n  cards.innerHTML=\'\';\n  st.textContent=current===\'day\'?\'Scanning for intraday setups…\':\'Ranking the universe…\';\n\n  try{\n    let url;\n    if(current===\'day\'){\n      url=`/api/intraday?capital=${amount}&risk_pct=${document.getElementById(\'rp\').value}`+\n        `&limit_universe=${document.getElementById(\'limit\').value}`+\n        `&min_price=${+document.getElementById(\'minPrice\').value}&max_price=${effectiveMax()}`;\n    }else{\n      url=`/api/portfolio?amount=${amount}&universe=nifty200&top_n=8`;\n    }\n\n    const r=await fetch(url),d=await r.json();\n    if(!r.ok) throw Error(d.detail||\'The scan did not complete\');\n\n    current===\'day\'?renderIntraday(d,amount):renderRanking(d,amount);\n  }catch(e){\n    st.textContent=\'The scan did not complete: \'+e.message;\n  }finally{\n    go.disabled=false;\n  }\n}\n\nfunction renderRanking(d,amount){\n  const b=d.basket;\n  document.getElementById(\'regime\').innerHTML=`NIFTY trend <b>${esc(d.market_regime.toLowerCase())}</b>`;\n\n  if(d.hold_cash){\n    document.getElementById(\'status\').innerHTML=\n      `<b>The rule says hold cash this month.</b> The NIFTY is below its 200-day average, `+\n      `which is where this strategy has historically done worst. The ranking is below if `+\n      `you want to see it anyway.`;\n  }else{\n    document.getElementById(\'status\').innerHTML=\n      `Ranked <b>${d.ranked}</b> of ${d.universe_size} stocks. Buying <b>${b.names}</b> `+\n      `${b.names===1?\'name\':\'names\'} with ${fmt(b.capital_deployed)}, leaving `+\n      `${fmt(b.cash_left)} uninvested.`+(b.narrowed_for_budget?`<br>${esc(b.note)}`:\'\');\n  }\n\n  document.getElementById(\'cards\').innerHTML=d.top.length?d.top.map((x,i)=>{\n    const a=x.affordability,v=x.historical_value_band,s=x.signals;\n    return `<article class="entry">\n      <div class="rank">${i+1}</div>\n      <div>\n        <div class="head">\n          <h3 class="name">${esc(x.symbol)}</h3>\n          <div class="score">${Number(x.model_score).toFixed(1)}<i> of 100</i></div>\n        </div>\n        <p class="line">${fmt(a.share_price)} a share · ${a.shares} shares for\n          ${fmt(a.capital_deployed)}${a.unfunded?\' · below your per-name budget, not funded\':\'\'}</p>\n        ${strip(x.historical_1m_range)}\n        <div class="rows">\n          ${v?row(\'This \'+fmt(a.capital_deployed)+\' in a middle month\',\n                  fmt(v.low)+\' to \'+fmt(v.high)):\'\'}\n          ${v?row(\'In the worst 1 month in 20\',fmt(v.worst_5pct)):\'\'}\n          ${row(\'Three-month return, against the index\',s.relative_strength_3m_pct+\'%\')}\n          ${row(\'Distance below its 52-week high\',Math.abs(s.below_52w_high_pct)+\'%\')}\n          ${row(\'Daily swing, typical\',s.daily_volatility_pct+\'%\')}\n        </div>\n        <div class="why">Ranked here because it is\n          ${s.above_ema50?\'above\':\'below\'} its 50-day average and\n          ${s.above_ema200?\'above\':\'below\'} its 200-day, returned ${s.return_3m_pct}% over three\n          months and ${s.return_6m_pct}% over six.\n          <ul>\n            <li><strong>The range is history, not a forecast.</strong> It shows what this stock has\n              done before, not what it will do.</li>\n            <li>The model beat the index in 49% of backtested months.</li>\n          </ul>\n        </div>\n      </div>\n    </article>`;\n  }).join(\'\'):\n    `<div class="empty"><b>No ranking came back.</b>Market data was unavailable for the universe.\n      Try again in a minute.</div>`;\n}\n\nfunction renderIntraday(d,capital){\n  const st=document.getElementById(\'status\');\n  st.innerHTML=`Scanned <b>${d.analysed}</b> stocks, <b>${d.matched_price_filter}</b> fit your price `+\n    `range, <b>${d.top.length}</b> produced a setup.`;\n\n  document.getElementById(\'cards\').innerHTML=d.top.length?d.top.map((x,i)=>`\n    <article class="entry">\n      <div class="rank">${i+1}</div>\n      <div>\n        <div class="head">\n          <h3 class="name">${esc(x.symbol)}</h3>\n          <div class="signal ${x.signal===\'BUY\'?\'buy\':\'sell\'}">${esc(x.signal)}</div>\n        </div>\n        <p class="line">${fmt(x.price)} a share · scored ${x.confidence} of 100 · signalled at\n          ${new Date(x.signal_time).toLocaleTimeString([],{hour:\'2-digit\',minute:\'2-digit\'})}</p>\n        <div class="rows">\n          ${row(\'Enter at\',\'₹\'+x.entry)}\n          ${row(\'Stop out at\',\'₹\'+x.stop_loss)}\n          ${row(\'First target\',\'₹\'+x.target1)}\n          ${row(\'Second target\',\'₹\'+x.target2)}\n          ${row(\'Size for \'+x.risk_pct+\'% risk\',x.quantity+\' shares, \'+fmt(x.capital_used))}\n          ${row(\'Most you could buy\',x.max_affordable_qty+\' shares\')}\n          ${row(\'Cash left over\',fmt(x.cash_left))}\n        </div>\n        <div class="why">What triggered it:\n          <ul>${x.reasons.map(v=>`<li>${esc(v)}</li>`).join(\'\')}</ul>\n          <ul><li><strong>The score is not a probability of profit.</strong> Leave if the stop\n            is hit.</li></ul>\n        </div>\n      </div>\n    </article>`).join(\'\'):\n    `<div class="empty"><b>No trade today.</b>Nothing in your price range set up cleanly enough.\n      Widening the price range or scanning more stocks may surface one.</div>`;\n}\n\nfunction table(title,rows,monthly){\n  if(!rows||!rows.length) return \'\';\n  const head=monthly\n    ?[\'Group\',\'Samples\',\'Closed up\',\'Beat NIFTY\',\'Average\']\n    :[\'Group\',\'Signals\',\'Hit target\',\'Closed up\',\'Average\'];\n  const body=rows.map(r=>monthly\n    ?`<tr><td>${esc(r.group)}</td><td>${r.samples}</td><td>${r.positive_after_1m_rate}%</td>\n       <td>${r.beat_nifty_rate}%</td><td>${r.avg_return_pct}%</td></tr>`\n    :`<tr><td>${esc(r.group)}</td><td>${r.signals}</td><td>${r.target1_hit_rate}%</td>\n       <td>${r.positive_outcome_rate}%</td><td>${r.avg_r}R</td></tr>`).join(\'\');\n  return `<div class="caveat"><h3>${title}</h3><div class="scroll"><table>\n    <thead><tr>${head.map(h=>`<th>${h}</th>`).join(\'\')}</tr></thead>\n    <tbody>${body}</tbody></table></div></div>`;\n}\n\nasync function runStrategyTest(){\n  const st=document.getElementById(\'status\'),cards=document.getElementById(\'cards\');\n  const hold=document.getElementById(\'btHold\').value;\n  const topN=document.getElementById(\'btTopN\').value;\n  const regime=document.getElementById(\'btRegime\').value;\n\n  st.textContent=\'Simulating whole-share trades across ten years, charging costs and tax on \'+\n    \'every rebalance. This takes a minute.\';\n\n  try{\n    const r=await fetch(`/api/backtest/strategy?top_n=${topN}&hold_days=${hold}`+\n      `&regime_filter=${regime}&universe=nifty200&period=10y`);\n    const d=await r.json();\n    if(!r.ok) throw Error(d.detail||\'The test did not complete\');\n\n    const c=d.config,verdict=d.significant\n      ?\'This edge clears the usual bar for statistical significance.\'\n      :\'This edge does not clear the usual bar. At this sample size it is not \'+\n       \'distinguishable from luck.\';\n\n    st.innerHTML=`Simulated <b>${d.periods_evaluated}</b> rebalances over ${d.years} years `+\n      `across ${c.symbols_with_history} stocks.`;\n\n    cards.innerHTML=`<article class="entry"><div class="rank">↳</div><div>\n      <div class="head"><h3 class="name">${c.top_n} stocks, every\n        ${c.hold_days===21?\'month\':c.hold_days===63?\'quarter\':c.hold_days+\' days\'}</h3></div>\n      <p class="line">${c.regime_filter?\'Moves to cash below the 200-day average. \':\'\'}Whole\n        shares from ${fmt(c.starting_capital)}, costs and tax charged on every trade.</p>\n      <div class="rows metrics">\n        ${row(\'Ended with\',fmt(d.final_capital))}\n        ${row(\'NIFTY over the same period\',fmt(d.benchmark_final_capital))}\n        ${row(\'Annual return\',d.cagr_pct+\'%\')}\n        ${row(\'NIFTY annual return\',d.benchmark_cagr_pct+\'%\')}\n        ${row(\'Rebalances that beat the index\',d.beat_benchmark_pct+\'%\')}\n        ${row(\'Average gain over the index\',d.avg_excess_pct+\'% per rebalance\')}\n        ${row(\'Is that real or luck\',\n              \'t = \'+d.excess_t_stat+(d.significant?\', real\':\', luck is not ruled out\'))}\n        ${row(\'Deepest fall\',d.max_drawdown_pct+\'%\')}\n        ${row(\'Paid in costs\',fmt(d.total_costs_paid))}\n        ${row(\'Paid in tax\',fmt(d.total_tax_paid))}\n        ${row(\'Costs and tax, per year\',d.cost_and_tax_drag_pct_per_year+\'% of the portfolio\')}\n        ${c.regime_filter?row(\'Rebalances spent in cash\',d.periods_in_cash):\'\'}\n      </div>\n      <div class="caveat"><h3>How to read this</h3>\n        <p>${verdict}</p>\n        <p>${esc(d.reading)}</p>\n      </div>\n      <div class="caveat"><h3>What it still does not model</h3>\n        <ul>\n          <li>The stock list is today\'s index. Names that fell out are missing, which\n            flatters every result here.</li>\n          <li>Fills are assumed at the closing price plus slippage.</li>\n          <li>Dividends are in the price series but dividend tax is not charged.</li>\n        </ul>\n      </div>\n    </div></article>`;\n  }catch(e){\n    st.textContent=\'The test did not complete: \'+e.message;\n  }\n}\n\nasync function runBacktest(){\n  const engine=document.getElementById(\'btEngine\').value;\n  const limit=document.getElementById(\'btLimit\').value;\n  const st=document.getElementById(\'status\'),cards=document.getElementById(\'cards\');\n\n  st.textContent=\'Replaying historical bars. This takes longer than a scan.\';\n  cards.innerHTML=\'\';\n\n  try{\n    if(engine===\'strategy\'){ await runStrategyTest(); return; }\n\n    const url=engine===\'intraday\'\n      ?`/api/backtest/intraday?limit_universe=${limit}&period=`+\n        `${document.getElementById(\'btWindow\').value}&max_hold_bars=12`\n      :`/api/backtest/monthly?limit_universe=${limit}&period=`+\n        `${document.getElementById(\'btMonthlyPeriod\').value}&horizon_days=21&min_technical_score=65`;\n\n    const r=await fetch(url),d=await r.json();\n    if(!r.ok) throw Error(d.detail||\'The test did not complete\');\n\n    const m=d.metrics,tested=d.symbols_tested.join(\', \');\n\n    if(engine===\'intraday\'){\n      st.innerHTML=`Measured from <b>${m.signals_tested}</b> historical signals on ${esc(tested)}.`;\n      cards.innerHTML=`<article class="entry"><div class="rank">↳</div><div>\n        <div class="head"><h3 class="name">Intraday, live rules</h3></div>\n        <p class="line">${esc(d.scope)}</p>\n        <div class="rows metrics">\n          ${row(\'Signals tested\',m.signals_tested)}\n          ${row(\'Reached the first target\',m.target1_hit_rate+\'%\')}\n          ${row(\'Closed positive\',m.positive_outcome_rate+\'%\')}\n          ${row(\'Average per signal\',m.avg_r+\'R\')}\n          ${row(\'Profit factor\',m.profit_factor)}\n          ${row(\'Deepest drawdown\',m.max_drawdown_r+\'R\')}\n          ${row(\'Targets, stops, timeouts\',\n                m.target1_hits+\', \'+m.stop_hits+\', \'+m.timeouts)}\n          ${row(\'Average winner against loser\',m.avg_winner_r+\'R against \'+m.avg_loser_r+\'R\')}\n        </div>\n        ${table(\'By direction\',d.by_signal)}\n        ${table(\'By model score\',d.by_confidence)}\n        ${table(\'By share price\',d.by_price)}\n        ${table(\'By time of day\',d.by_time)}\n        <div class="caveat"><h3>What this test cannot tell you</h3>\n          <ul>${d.limitations.map(x=>`<li>${esc(x)}</li>`).join(\'\')}</ul></div>\n      </div></article>`;\n    }else{\n      st.innerHTML=`Measured from <b>${m.samples_tested}</b> non-overlapping windows on ${esc(tested)}.`;\n      cards.innerHTML=`<article class="entry"><div class="rank">↳</div><div>\n        <div class="head"><h3 class="name">Monthly, technical proxy</h3></div>\n        <p class="line">${esc(d.scope)}</p>\n        <div class="rows metrics">\n          ${row(\'Windows tested\',m.samples_tested)}\n          ${row(\'Closed up after a month\',m.positive_after_1m_rate+\'%\')}\n          ${row(\'Beat the NIFTY\',m.beat_nifty_rate+\'%\')}\n          ${row(\'Average stock return\',m.avg_stock_return_pct+\'%\')}\n          ${row(\'Average NIFTY return\',m.avg_nifty_return_pct+\'%\')}\n          ${row(\'Difference\',m.avg_excess_return_pct+\'%\')}\n        </div>\n        ${table(\'By technical score\',d.by_score,true)}\n        <div class="caveat"><h3>Why this is not full-model accuracy</h3>\n          <ul>${d.limitations.map(x=>`<li>${esc(x)}</li>`).join(\'\')}</ul></div>\n      </div></article>`;\n    }\n  }catch(e){\n    st.textContent=\'The test did not complete: \'+e.message;\n  }\n}\n\nupdatePriceText();\nbacktestEngineChanged();\n</script>\n</body>\n</html>\n'
